<script setup lang="ts">
import {ref} from "vue";import {request,upload} from "../../api";import {onShow} from "@dcloudio/uni-app";
const d=new Date(),date=ref(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`),title=ref(""),body=ref(""),mood=ref("甜蜜"),visibility=ref("shared"),media=ref<any[]>([]);
function photos(){uni.chooseImage({count:6,success:async r=>{for(const p of r.tempFilePaths)media.value.push(await upload(p))}})}async function save(){try{await request("/api/v1/entries","POST",{title:title.value,body:body.value,mood:mood.value,happened_on:date.value,visibility:visibility.value,media_ids:media.value.map(x=>x.id)});title.value="";body.value="";media.value=[];uni.showToast({title:"已同步"});setTimeout(()=>uni.switchTab({url:"/pages/index/index"}),500)}catch(e:any){uni.showToast({title:e.message,icon:"none"})}}onShow(()=>{});
</script>
<template><view class="page"><input v-model="date" class="input"/><input v-model="title" class="input" placeholder="给今天起个标题"/><textarea v-model="body" class="area" placeholder="写下此刻想说的话…"/><view class="row"><picker :range="['开心','甜蜜','想你','平静','委屈']" @change="mood=['开心','甜蜜','想你','平静','委屈'][$event.detail.value]"><text>心情：{{mood}}</text></picker><switch :checked="visibility==='shared'" color="#c45c6a" @change="visibility=$event.detail.value?'shared':'private'"/> <text>{{visibility==='shared'?'共享':'仅自己'}}</text></view><view class="pics"><image v-for="m in media" :key="m.id" :src="m.thumb_url||m.url" mode="aspectFill"/></view><button class="photo" @click="photos">添加照片</button><button class="save" @click="save">保存并同步</button></view></template>
<style scoped>.page{padding:32rpx}.input,.area{display:block;box-sizing:border-box;width:100%;background:white;padding:24rpx;border-radius:18rpx;margin-bottom:18rpx}.area{height:360rpx}.row{display:flex;align-items:center;gap:18rpx;background:white;padding:24rpx;border-radius:18rpx}.pics{display:flex;flex-wrap:wrap;gap:12rpx;margin-top:18rpx}.pics image{width:190rpx;height:190rpx;border-radius:16rpx}.photo{background:#fff;color:#c45c6a;margin-top:22rpx}.save{background:#c45c6a;color:white;margin-top:22rpx}</style>

